from chonkie import RecursiveChunker, RecursiveLevel, RecursiveRules

# Dữ liệu mẫu; có thể thay bằng văn bản của một heading từ Docling.
text = """
Trong lĩnh vực giáo dục đại học, chất lượng đóng vai trò hết sức quan trọng trong việc giải trình về uy tín, vị thế của một cơ sở giáo dục đại học (CSGDĐH) hay một chương trình đào tạo (CTĐT), Thông qua các phương tiện truyền thông, có thể thấy rằng những đại học/trường đại học được xếp ởạng cao đều là những đơn vị có nhiều CTĐT đạt các tiêu chuẩn kiểm định chất lượng. Tiêu chuẩn kiểm định chất lượng nào càng có uy tín thì CTĐT đạt tiêu chuẩn đó càng được xem là có chất lượng tốt.
Các tài liệu trong và ngoài nước nêu lên rất nhiều khái niệm, định nghĩa khác nhau về chất lượng, bảo đảm chất lượng, kiểm định chất lượng. Dưới đây là cách hiếu một số khái niệm khác nhau được sử dụng trong cuốn sách này:
- Chất lượng: Đây là một khái niệm có rất nhiều định nghĩa khác nhau và mang tính tương đối, tùy thuộc vào góc nhìn của người đánh giá
chất lượng. Khi nhu cầu của con người đối với một đối tượng, vấn đề hay lĩnh vực nào đó được đáp ứng thì chất lượng có thể được xem là sự phù hợp với nhu cầu hay mục tiêu của khách hàng; và đây cũng chính là quan điểm về chất lượng trong cuốn sách này, Chẳng hạn như khi bạn đi chọn mua một chiếc áiệu vải làm bạn hải lòng; giá cả cũng phù hợp với thu nhập hàng tháng của bạn thì chiếc áo ấy có thể được xem là có chất lượng đối với bạn. Tuy nhiên, chiếc áo ấy có thể là chưa phù hợp với một người khác về mức độ thẩm mỹ hay giá cả... Như vậy để đánh giá chất lượng thông thường ta cần phải có mộ chuẩn để kiểm soát chất lượng. Ví dụ, bạn có thể đặt ra tiêu chuẩn cho chiếc áo cần chọn: kiểu dáng - phù hợp với người trẻ, chất liệu vải - 80% cotton trở lên; giá cả phải hợp lý, không quá 500.000 đồng, Tuy nhiên, đối với một người có thu nhập rất cao thì tiêu chí chất lượng của chiếc áo có thểải rất đẹp, nổi bật; chất liệu vải - 100% cotton; giá cả không thành vấn đề, Một sản phẩm, đối tượng có thể là đạt yêu cầu về chất lượng đối với người này song chưa hắn đã đạt yêu cầu về chất lượng đối với người khác.
Trong lĩnh vực giáo dục đại học, có thể thấy uy tín, thương hiệu cũng như chất lượng đào tạo của những trường đại học nổi tiếng trên thế giới như: Harvard (Hoa Kỳ), Oxford, Cambridge (Anh) được khẳng định thông qua danh tiếng về mặt khoa học với những phát minh sáng chế ảnh hưởng đến cả thế giới; các nhà khoa học lừng danh, nhiều người đạt giải Nobel; đa số người học tốt nghiệp các trường này thường được các nhà tuyển dụng sẫn sàng trả lương cao hoặc là những nhà khoa học, doanh nhân thành đạt - cung cấp việc làm cho nhiều người khác; nhiều cựu người học (cựu sinh viên, học viên, nghiên cứười thành danh, nhiều người là Tổng thống Hoa Kỳ, Thủ tướng Anh,.. Như vậy, chất lượng của một cơ sở giáo dục (CSGD) sẽ được nhìn nhận, đánh giá thông qua các tiêu chí như chất lượng của đội ngũ giảng viên, cơ sở vật chất, phòng thí nghiệm - thực hành, cảnh quan trường; chất lượng của các CTĐT; ch sau khi tốt nghiệp, đặc biệt là uy tín, vị thế của cựu người học trong xã hội...
Tương tự như đối với CSGD, việc xác định những tiêu chuẩn để đánh giá chất lượng đối với một CTĐT là rất cần thiết, Nếu bộ tiêu chuẩn càng có tính chất khắt khe, yêu cầu cao thì có thể xem CTĐT đáp ứng được đưa vào tiêu chuẩn để đánh giá chất lượng CTĐT sẽ là chất lượng của đội ngũ giảng viên giảnt lượng hoạt động các tiêu chuẩn này đạt chất lượng rất tốt. Thông thường các yếu tố cần thường giảng dạy (thường được đánh giá quá việc đo lường mức độ người học thái trị) đạt được các chuẩn đầu ra); chất lượng của cơ sở vật chất, trang thiết bị thí nghiệm, thực hành, thư viện và nguồn học liệu; i tốt nghiệp và uy tín của người học....
- Bảo đảm chất lượng (BĐCL) đối với một tổ chức là toàn bộ các hoạt động có kế hoạch và mang tính hệ thống được thực hiện để quản lý chất lượng, có đủ mức cần thiết để tạo niềm tín rằng sản phẩm hay dịch Vụ của tổ chức sẽ đáp ứng các yêu cầu về chất lượng. BĐCL có hai mục đích chính: BĐCL trong nộlòng tín cho tổ chức (BĐCL bên trong) và BĐCL đối với bên ngoài tổ chức nhằm tạo niềm tin cho khách hàng và những người khác có liên quan về chất lượng sản phẩm, dịch vụ mà tổ chức đó cung cấp (BĐCL bên ngoài). Đối với một trường đại học, BĐCL bên trong là việc phải duy trì các chuẩn mực của một g(ví dụ giảng viên phải có trình độ Thạc sĩ trở thuật lên theo quy định của nước ta), năng lực giảng dạy và nghiên cứu khoa người học (thông qua đánh giá kết quả hoạt động giảng dạy, sản phẩm hay công bố khoa học của giảng viên); duy trì chuẩn mực về quá trình giảng dạy, lên lớp của giảng viên (thô giảng dạy và phản hồi của người học); chuẩn mực về việc cập nhật, hiện đại hóa các nội dung giảng dạy (thông qua hệ thống rà soát CTĐT, cập nhật nội dung của các học phần, các chuẩn đầu ra học phần); chuẩn mực về cơ sở vật chất, thí nghiệm - thực hành (thông qua việc rà soát, hiện đại hóa các điềbị thí nghiệm - thực hành, nâng cấp học liệu), Tập hợp các quy định, tiêu chuẩn (hay chuẩn mực), hệ thống theo dõi, giám sát việc thực hiện và đáp ứng các tiêu chuẩn này cũng như công tác cải tiến liên tục chất lượng chính là hệ thống BĐCL bên trong. Để thực hiện tốt hệ thống BĐCL bên trong, các Chuyên trách về công tác BĐCL như Phòng/Ban/Trung tâm Đảm bảo Chất lượng Giáo dục (ĐBCLGD), mạng lưới BĐCL trong toàn trường từ cấp lãnh đạo đến các phòng ban chức năng và các khoa, có sự ủng hộ từ lãnh đạo nhà nhà nội trường về nguồn tài chính, chính sách, công tác đào tạo bồi dưỡng chuyên môn về à hình thành nên văn hóa chất lượng cũng đóng vai trò rất quan trọng. Nếu mỗi cán bộ, giảng viên, người học đều luôn làm việc với tinh thần "chất lượng" cao nhất, tuân thủ đầy đủ các yêu cầu, quy định của hệ thống BĐCL bên trong thì việc công nhận chất lượng đối với CSGD và các CTĐT sẽ là kết quả 
Muốn tạo niềm tin về chất lượng của CTĐT với xã hội thì nhà trường cần có tuyên bố về chất lượng của CTĐT với xã hội như công khai về CTĐT, chuẩn đầu ra của CTĐT, công khai về chất lượng của đội ngũ giảng viên, công khai về uy tín học thuật thông qua các sản phẩm khoa học, các công trình khoa học về điều kiện cơ sở vật chất, công khai về chất lượng của người học sau khi tốt nghiệp thông qua tỷ lệ người học có việc làm sau khi tốt nghiệp... Đây chính là với xã hội của CSGDĐH; phụ huynh và bản thân người học có quyền sao các trường đại học hàng đầu thế giới kể trên như: Harvard (Hoa Kỳ),
hệ thống BĐCL bên ngoài cần có nhằm thực hiện trách nhiệm giải trình theo dõi, tự đánh giá về chất lượng và chọn lựa trường hay ngành nghề đào tạo phù hợp để đăng ký học. Từ đây ta có thể dễ dàng hiểu được vì Oxford, Cambridge (Anh) luôn là niềm mơ ước để theo học của nhiều học sinh trên toàn thế 
- Kiểm định chất lượng (KĐCL): Như đã nêu trên, mỗi trường đại nhà nhau học đều có quyền công bố về các thông số liên quan đến chất lượng của nhà trường và các CTĐT. Tuy nhiên, câu hỏi đặt ra là các tuyên bố này liệu có chính xác không, chất lượng đào tạo thực tế của nhà trường qua các CTĐT liệu clà có những thông số tốt, nhưng cũng có những mặt còn yếu kém? Để tạo niềm tin đối với xã hội về chất lượng của CSGDĐH cũng như chất lượng của các CTĐT, các tổ chức KĐCL giáo dục được thành lập để có thể đánh giá chất lượng của CSGD và CTĐT từ phía bên ngoài (còn gọi là đánh giá ngoài) và tuyên bốđáp ứng của CSGD và CTĐT đối với các tiêu chuẩn yêu cầu của tổ chức kiểm định đó. KĐCL giáo dục gắn liền với hai yếu tố là đánh giá ngoài và công nhận chất lượng giáo dục. CSGD hoặc CTĐT có thể được công nhận là đạt hay chưa đạt đối với tiêu chuẩn chất lượng của tổ chức kiểm định. Bên cạnh đó, tổ ỉ ra được những điểm mạnh và điểm tồn tại của CSGD hay CTĐT để nhà
trường nhận biết và phát huy những điểm mạnh, có giải pháp khắc phục những điểm tồn tại và liên tục cải tiến.
KĐCL trong giáo dục đại học thường có hai hình thức là KĐCL CSGD và KĐCL CTĐT. Tại Việt Nam, theo Luật Sửa đổi, bổ sung một số điều của Luật Giáo dục đại học có hiệu lực kể từ tháng 7/2019 thì KĐCL là bắt buộc đối với tất cả các CSGD và CTĐT. Chu kỳ KĐCL đối với CSGD cũng như CTĐT là 05 năm, Theo ợng giáo dục đại học giai đoạn 2019-2025 của Bộ Giáo dục và Đào tạo (BGDĐT) cũng như kết luận của Thứ trưởng BGDĐT Hoàng Minh Sơn tại Hội nghị Tổng kết công tác bảo đảm và kiểm định chất lượng giáo dục đại học, cao đẳng sư phạm giai đoạn 2011-2020, một trong những mục tiêu chiến lược quan trọng đư là ?trên 35% CTĐT được kiểm định trong nước hoặc nước ngoài, trong đó 100% CTĐT giáo viên ở tất cả các trình độ được kiểm định? [1], [2]. Đây là công việc của toàn hệ thống, của toàn bộ CSGDH, chứ không phải của chỉ riêng bộ phận đào tạo hay Phòng/Ban/Trung tâm ĐBCLGD.
Để có thể thực hiện thành công việc KĐCL thì việc xây dựng thành công hệ thống BĐCL bên trong là yếu tố sống còn, Trong đó, ý chí quyết tâm của lãnh đạo nhà trường, công tác quản trị đại học, các chính sách hỗ trợ, công tác chuyên môn về BĐCL đóng vai trò then chốt, các phương pháp, công cụ, kế ho phải cụ thể, hợp lý, Để biết tình trạng chất lượng của CSGD hay CTĐT có đáp ứng được các tiêu chuẩn KĐCL hay không và mức độ đáp ứng như thế nào thì cần phải thực hiện việc tự đánh giá chất lượng của CSGD hay CTĐT.
Các phần tiếp theo trong cuốn sách này sẽ tập trung đề cập chủ yếu thuật các nội dung liên quan đến BĐCL và KĐCL đối với CTĐT. Để có định hướng tốt trong việc hoàn thiện hệ thống BĐCL bên trong, hướng đến thành công trong việc KĐCL CTĐT, việc hiểu rõ các tiêu chuẩn kiểm định là rất quan trọng. CTĐlượng nếu đạt các yêu cầu về mục tiêu, chuẩn đầu ra, cấu trúc và nội dung, phương pháp giảng dạy - học tập, kiểm tra - đánh giá, đội ngũ cán bộ, người học, cơ sở vật chất... Tuy nhiên, các yêu cầu này là khác nhau trong các tiêu chuẩn kiểm định khác nhau.
Để đánh giá chất lượng của đa số các CTĐT bậc đại học trở lên, hiện nay các trường đại học nước ta đang sử dụng 11 tiêu chuẩn đánh giá chất lượng CTĐT ban hành kèm theo Thông tư số 04/2016/TT-BGDĐT [3], Ngoài ra, để đánh giá chất lượng các CTĐT giáo viên trình độ cao đẳng sư phạm và trung cấp sư p hành thêm Thông tư số 02/2020/TT-BGDT?? gồm 10 tiêu chuẩn, có thể xem như phiên bản gọn nhẹ hơn của Thông tự số 04/2016/TT-BGDĐT. Ngoài các tiêu chuẩn trên, một số trường đại học Việt Nam còn thực hiện đánh giá chất lượng CTĐT theo các tiêu chuẩn khác như AUN-QA (được thiết kế bởi Mạng lưới các t Á - gọi tắt là AUN), tiêu chuẩn ABET, AACSB, ACBSP của Hoa Kỳ hay tiêu chuẩn FIBAA của châu Âu.. Vì vậy công tác BĐCL, tự đánh giá và đánh giá ngoài chất lượng CTĐT cần triển khai bám sát theo bộ tiêu chuẩn được xác định trong kế hoạch, định hướng KĐCL giáo dục của CSGD.
"""

# Các mức được thử từ trên xuống khi đoạn còn quá dài.
rules = RecursiveRules(levels=[
    RecursiveLevel(delimiters=["\n\n"], include_delim="prev"),
    RecursiveLevel(delimiters=["\n"], include_delim="prev"),
    RecursiveLevel(delimiters=[". ", "? ", "! "], include_delim="prev"),
    RecursiveLevel(whitespace=True),
    RecursiveLevel(),
])

# tokenizer="character": chunk_size được tính bằng ký tự, không phải token.
chunker = RecursiveChunker(tokenizer="character", chunk_size=2000, rules=rules)
chunks = chunker.chunk(text)

for i, chunk in enumerate(chunks, start=1):
    print(f"\n{'=' * 50}\nCHUNK {i}")
    print(f"Số ký tự: {len(chunk.text)}")
    print(chunk.text)
